static void auacer_add_entry ( struct auacer_chan * chan ) { struct auacer_dmalist * q ; q = & chan -> dmalist [ chan -> ptr ] ; DPRINTF ( ALI_DEBUG_INTR , ( "auacer_add_entry: %p = %x @ 0x%x\n" , q , chan -> blksize / 2 , chan -> p ) ) ; q -> base = htole32 ( chan -> p ) ; chan -> p += chan -> blksize ; if ( chan -> p >= chan -> end ) { chan -> p = chan -> start ; } if ( ++ chan -> ptr >= ALI_DMALIST_MAX ) { chan -> ptr = 0 ; } } 